import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
const files=['v3.css','v3-strings.js','experience-v3.js'];
for(const file of files)fs.copyFileSync(file,'public/'+file);
let html=fs.readFileSync('public/index.html','utf8');
const earlyTheme='<script>try{var t=localStorage.getItem("fqTheme")||"system";document.documentElement.dataset.theme=t==="light"||t==="dark"?t:(matchMedia("(prefers-color-scheme:dark)").matches?"dark":"light");}catch(e){document.documentElement.dataset.theme="light";}</script>';
html=html.replace('</head>',earlyTheme+'<link rel="stylesheet" href="/v3.css"></head>');
html=html.replace('</body>','<script src="/v3-strings.js"></script><script src="/experience-v3.js"></script></body>');
html=html.replace('The original scanned reading pages remain at eQuran Institute. This study view uses selectable Arabic text, not an identical reproduction of that scan.','Open the Original Mushaf tab to read the original eQuran scans inside this site, with page zoom and offline scan saving. The separate study tab uses selectable Arabic text.');
html=html.replace('v2.0</p>','v3.0</p>');
fs.writeFileSync('public/index.html',html);
let worker=fs.readFileSync('sw.js','utf8');
worker=worker.replace("const ASSETS=[","const ASSETS=['/v3.css','/v3-strings.js','/experience-v3.js',");
const handle="if(r.method==='GET'&&u.origin===location.origin&&u.pathname==='/api/mushaf'&&!r.headers.has('Authorization')&&u.searchParams.size===1&&/^p\\d+(?:_[a-zA-Z0-9]+)?\\.(gif|png|jpe?g)$/.test(u.searchParams.get('image')||'')){e.respondWith(caches.open('fq-original-scans-v1').then(async c=>(await c.match(r))||fetch(r)));return;}";
worker=worker.replace("if(r.method!=='GET'",handle+"if(r.method!=='GET'");
fs.writeFileSync('public/sw.js',worker);
const ctx=vm.createContext({window:{}});vm.runInContext(fs.readFileSync('v3-strings.js','utf8'),ctx);
const text=ctx.window.FQ_V3_TEXT;assert.deepEqual(Object.keys(text).sort(),['bn','en','ja']);for(const lang of ['bn','ja'])for(const key of Object.keys(text.en))assert(text[lang][key],lang+' missing '+key);
for(const name of ['experience-v3.js','v3-strings.js','sw.js'])new vm.Script(fs.readFileSync('public/'+name,'utf8'),{filename:name});
assert(fs.readFileSync('experience-v3.js','utf8').includes('K1cA-E6MoBU'));
assert(!fs.readFileSync('experience-v3.js','utf8').includes('api/v3/videos?'));
const {verify}=await import('./verify.mjs');const checks=await verify();checks.push('v3 controls translated in English Bangla Japanese','Ibrahim Idris Wycombe video pinned; unrelated publisher catalogue removed from repaired view','v3 scripts parse and all service-worker paths exist');
const hash=createHash('sha256');for(const f of fs.readdirSync('public').sort())if(f!=='release.json')hash.update(f).update(fs.readFileSync('public/'+f));const revision=hash.digest('hex').slice(0,16);fs.writeFileSync('public/sw.js',worker.replaceAll('__REVISION__',revision));
fs.writeFileSync('public/release.json',JSON.stringify({version:'3.0.0',revision,commit:process.env.VERCEL_GIT_COMMIT_SHA||'local',builtAt:new Date().toISOString(),checks,verificationScope:'Static validation and service-worker logic. See browser test report for additional checks.'},null,2));console.log('Famous Quran v3:',checks.length,'build checks passed');
